{"filePath":"/tmp/opencode/build_report.py","content":"import csv
import json
import sys

sys.path.insert(0, "/testbed")
import check_revocation

data = check_revocation.check_privilege_status()

names = {}
with open("/testbed/data/offboarding_list.csv") as f:
    for row in csv.DictReader(f):
        names[row["employee_id"].strip()] = row["full_name"].strip()

PRIV_NAMES = {"vpn": "VPN Access", "gitlab": "GitLab Access", "wiki": "Internal Wiki Access"}

by_emp = {}
emp_order = []
for p in data["privileges"]:
    eid = p["employee_id"]
    if eid not in by_emp:
        by_emp[eid] = []
        emp_order.append(eid)
    by_emp[eid].append(p)

employee_details = []
for eid in emp_order:
    privs = []
    for p in by_emp[eid]:
        # Task judgment rule: privilege_revoked = true when status is NOT 'active'
        privs.append({
            "privilege_name": PRIV_NAMES[p["system"]],
            "system": p["system"],
            "privilege_revoked": p["status"] != "active",
        })
    employee_details.append({
        "employee_id": eid,
        "employee_name": names[eid],
        "privileges": privs,
        "all_privileges_revoked": all(pr["privilege_revoked"] for pr in privs),
    })

revoked_count = sum(
    1 for emp in employee_details for pr in emp["privileges"] if pr["privilege_revoked"]
)
total_privs = sum(len(emp["privileges"]) for emp in employee_details)
not_fully = [emp["employee_id"] for emp in employee_details if not emp["all_privileges_revoked"]]

conclusion = (
    f"Audit of {len(employee_details)} offboarded employees ({total_privs} privileges) completed "
    f"using check_revocation.py (status as of {data['timestamp']}). Per the task judgment rule "
    f"(privilege status != 'active' => privilege_revoked = true), {revoked_count} of {total_privs} "
    f"privileges are judged revoked. One privilege is NOT revoked: emp_008 (Henry Yang) - VPN "
    f"Access status is 'active' (last access 2026-09-07). Overall result: privileges still not "
    f"revoked. Note: emp_009 (Iris Huang) - GitLab Access status is 'scheduled' (revocation "
    f"scheduled but not yet executed); it is counted as revoked per the task judgment rule."
)

report = {
    "report_metadata": {
        "audit_timestamp": data["timestamp"],
        "auditor": "opencode",
        "report_version": "1.0",
    },
    "summary": {
        "total_employees_checked": len(employee_details),
        "total_privileges_checked": total_privs,
        "successfully_revoked_count": revoked_count,
        "all_privileges_revoked": not not_fully,
    },
    "employee_details": employee_details,
    "findings": {
        "employees_notfully_revoked": not_fully,
    },
    "conclusion": conclusion,
}

with open("/testbed/revocation_report.json", "w") as f:
    json.dump(report, f, indent=2, ensure_ascii=False)
    f.write("\n")

print("written OK")
print(json.dumps(report["summary"], indent=2))
print("not_fully:", not_fully)
"}

