import json
r = json.load(open('/testbed/revocation_report.json'))
def walk(o, path=''):
    if isinstance(o, dict):
        for k, v in o.items():
            assert not k.startswith('_comment_'), f'comment field left: {path}/{k}'
            walk(v, path + '/' + k)
    elif isinstance(o, list):
        for i, v in enumerate(o):
            walk(v, f'{path}[{i}]')
walk(r)
print('valid JSON, no _comment_ fields')
print('top-level keys:', list(r.keys()))
print('employees:', [(e['employee_id'], e['employee_name'], e['all_privileges_revoked']) for e in r['employee_details']])
print('emp_008 privs:', [p for p in r['employee_details'][7]['privileges']])
print('emp_009 privs:', [p for p in r['employee_details'][8]['privileges']])
print('findings:', r['findings'])
